SET SESSION group_concat_max_len=10000000;
SELECT 'User' AS table_name, COUNT(*) AS row_count, MD5(GROUP_CONCAT(id ORDER BY id SEPARATOR ',')) AS id_checksum, MD5(GROUP_CONCAT(id ORDER BY id SEPARATOR ',')) AS business_checksum FROM `User`;
SELECT 'CompanyProfile' AS table_name, COUNT(*) AS row_count, MD5(GROUP_CONCAT(id ORDER BY id SEPARATOR ',')) AS id_checksum, MD5(GROUP_CONCAT(id ORDER BY id SEPARATOR ',')) AS business_checksum FROM `CompanyProfile`;
